import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CDU0sSpB.js";const k=JSON.parse('{"title":"Phase 3 · Desktop Operation","description":"Let Hearth operate desktop software and cross-application workflows without open interfaces.","frontmatter":{"title":"Phase 3 · Desktop Operation","description":"Let Hearth operate desktop software and cross-application workflows without open interfaces.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-3.md","filePath":"en/delivery/stage-3.md","lastUpdated":1794015952000}'),r={name:"en/delivery/stage-3.md"};function i(n,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="phase-3-·-desktop-operation" tabindex="-1">Phase 3 · Desktop Operation <a class="header-anchor" href="#phase-3-·-desktop-operation" aria-label="Permalink to &quot;Phase 3 · Desktop Operation&quot;">​</a></h1><p>See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 Delivery Status</a> for implemented scope, verified paths, and deliberate gaps.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented code loop:</strong> Pairing for same-machine Windows devices, per-capability approval, observe, pause, resume, takeover, handback, and terminate, plus low-risk click, typing, key, and UIAutomation actions in allowlisted applications.</li><li><strong>Still open:</strong> Sensitive-region masking, isolated desktops, high-risk action preview and compensation, real UIA setvalue acceptance, and acceptance with at least 5 real desktop tasks. See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 delivery status</a>.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 3 lets Hearth operate desktop software and cross-application workflows that have no open interface. The order is observe first, take over second, low-risk actions third, and high-risk actions last. If the system cannot observe, pause, or hand over, it must not act automatically.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-3/3-1.html">3.1 Connect and inspect a desktop device</a></td><td>Make the device, scope, and stop control clear to the user.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/3-2.html">3.2 Observe the desktop and take over</a></td><td>Let the user see the work, pause, take over, and hand back.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/3-3.html">3.3 Complete desktop actions by risk level</a></td><td>Start with low-risk actions; high-risk actions need preview, confirmation, and recovery.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/3-4.html">3.4 Accept desktop operation</a></td><td>Prove with real desktop tasks that it is understandable, interruptible, and stoppable.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>First let the user see and trust the desktop device.</li><li>Then let the user observe, pause, and take over.</li><li>Then complete low-risk actions in allowlisted applications.</li><li>Only then open high-risk actions, with snapshots, compensation, and recovery drills.</li></ol>',10)])])}const u=t(r,[["render",i]]);export{k as __pageData,u as default};
